markers = [(2, 6), (3, 19), (4, 5), (7, 1), (8, 19), (12, 9), (17, 13), (19, 15)]

# Dense rows: all rows except 2-8 (block rows)
# AND markers might be overwritten
for r in range(20):
    if r not in [2,3,4,5,6,7,8]:
        # All 2s (dense wall)
        for c in range(20):
            result[r][c] = 2
    else:
        # Block rows: partial wall at 2-9
        for c in range(2, 10):
            result[r][c] = 2

# Add markers
for r, c in markers:
    if r in [2,3,4,5,6,7,8]:
        # Block row - marker preserved if not in wall
        if c < 2 or c >= 10:
            result[r][c] = 1

